/**
 * Algorithm library. Every algorithm here is checked by tests/algs.test.ts:
 * it must leave the first two layers intact, and every case in a set must be
 * a different case. Case diagrams are generated by applying the inverse
 * of the algorithm to a solved cube, so a picture can never disagree with its alg.
 *
 * Orientation convention: yellow on top (U), green in front (F).
 */

export type AlgSet = 'OLL' | 'PLL' | 'F2L' | 'OLL2' | 'PLL2' | 'BEG';

export interface Alg {
  id: string;
  set: AlgSet;
  name: string;
  group: string;
  alg: string;
  /** Alternative algorithms (also validated). */
  alts?: string[];
  /** Short recognition / execution hint. */
  tip?: string;
}

const oll = (n: number, group: string, alg: string, name = '', tip = ''): Alg => ({
  id: `OLL ${n}`,
  set: 'OLL',
  name: name || `OLL ${n}`,
  group,
  alg,
  tip,
});

